/*
 * Функция flang «Сканировать».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Взаимная хвостовая рекурсия с «Уложить литерал»: вызовы идут через батут.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param sostoyanie — «состояние»: «Лексер»
 * @param simvoly — «символы»: список: строка
 * @param poziciya — «позиция»: число
 * @param ostalos — «осталось»: число
 * @return значение: «Лексер»
 */
fl_status kompilyator_flang_skanirovat(fl_ctx *ctx, fl_value sostoyanie, fl_value simvoly, fl_value poziciya, fl_value ostalos, fl_value *result, fl_error *error) {
  fl_value args[4];
  args[0] = sostoyanie;
  args[1] = simvoly;
  args[2] = poziciya;
  args[3] = ostalos;
  FL_TRY(fl_enter(ctx, "Сканировать", error));
  {
    const fl_status status = fl_trampoline(ctx, kompilyator_flang_skanirovat_step, args, 4, "Сканировать",
                                           result, error);
    fl_leave(ctx);
    return status;
  }
}

/* Шаг батута для «Уложить литерал»: значение либо отскок к соседу по рекурсии. */
static fl_status kompilyator_flang_ulozhit_literal_step(fl_ctx *ctx, const fl_value *args, fl_bounce *bounce, fl_value *result,
                                                        fl_error *error) {
  fl_value sostoyanie = args[0]; /* «состояние» */
  fl_value simvoly = args[1]; /* «символы» */
  fl_value poziciya = args[2]; /* «позиция» */
  fl_value chtenie = args[3]; /* «чтение» */
  fl_value zakryvayuschaya = args[4]; /* «закрывающая» */
  fl_value vid = args[5]; /* «вид» */
  fl_value nomer = args[6]; /* «номер» */
  fl_value mesto = args[7]; /* «место» */
  fl_value fl_t712 = fl_nothing();
  FL_TRY(fl_field_get(ctx, chtenie, "сломано", &fl_t712, error));
  bool fl_t713 = false;
  FL_TRY(fl_cond(ctx, fl_t712, &fl_t713, error));
  if (fl_t713) {
    return kompilyator_flang_s_oshibkoy(ctx, sostoyanie, kompilyator_flang_text_246, kompilyator_flang_text_258, nomer, mesto, result, error);
  } else {
    fl_value fl_t714 = fl_nothing();
    FL_TRY(fl_field_get(ctx, chtenie, "закрыто", &fl_t714, error));
    bool fl_t715 = false;
    FL_TRY(fl_cond(ctx, fl_t714, &fl_t715, error));
    if (fl_t715) {
      bool fl_t716 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(vid, kompilyator_flang_text_222)), &fl_t716, error));
      fl_value fl_t717 = fl_nothing();
      if (fl_t716) {
        fl_value fl_t718 = fl_nothing();
        FL_TRY(fl_field_get(ctx, chtenie, "значение", &fl_t718, error));
        fl_value fl_t719 = fl_nothing();
        FL_TRY(kompilyator_flang_token_imeni(ctx, fl_t718, kompilyator_flang_text_169, fl_flag(true), nomer, mesto, &fl_t719, error));
        fl_t717 = fl_t719;
      } else {
        fl_value fl_t720 = fl_nothing();
        FL_TRY(fl_field_get(ctx, chtenie, "значение", &fl_t720, error));
        fl_value fl_t721 = fl_nothing();
        FL_TRY(kompilyator_flang_token_literala(ctx, fl_t720, nomer, mesto, &fl_t721, error));
        fl_t717 = fl_t721;
      }
      const fl_value token = fl_t717; /* пусть «токен» */
      fl_value fl_t722 = fl_nothing();
      FL_TRY(kompilyator_flang_s_tokenom(ctx, sostoyanie, token, &fl_t722, error));
      fl_value fl_t723 = fl_nothing(); /* «хвост» */
      FL_TRY(fl_b_hvost(ctx, simvoly, &fl_t723, error));
      fl_value fl_t724 = fl_nothing();
      FL_TRY(fl_add(ctx, poziciya, fl_number(1.0), &fl_t724, error));
      fl_value fl_t725 = fl_nothing();
      FL_TRY(fl_field_get(ctx, chtenie, "съедено", &fl_t725, error));
      fl_value fl_t726 = fl_nothing();
      FL_TRY(fl_sub(ctx, fl_t725, fl_number(1.0), &fl_t726, error));
      /* хвостовой вызов «Сканировать» — отскок, а не кадр стека */
      bounce->args[0] = fl_t722;
      bounce->args[1] = fl_t723;
      bounce->args[2] = fl_t724;
      bounce->args[3] = fl_t726;
      bounce->next = kompilyator_flang_skanirovat_step;
      return FL_OK;
    } else {
      fl_value fl_t727 = fl_nothing();
      FL_TRY(fl_field_get(ctx, chtenie, "съело перевод", &fl_t727, error));
      bool fl_t728 = false;
      FL_TRY(fl_cond(ctx, fl_t727, &fl_t728, error));
      fl_value fl_t729 = fl_nothing();
      if (fl_t728) {
        fl_value fl_t730 = fl_nothing();
        FL_TRY(fl_field_get(ctx, chtenie, "значение", &fl_t730, error));
        fl_t729 = fl_t730;
      } else {
        fl_value fl_t731 = fl_nothing();
        FL_TRY(fl_field_get(ctx, chtenie, "значение", &fl_t731, error));
        fl_value fl_t732 = fl_nothing();
        FL_TRY(fl_concat(ctx, fl_t731, kompilyator_flang_text_211, &fl_t732, error));
        fl_t729 = fl_t732;
      }
      const fl_value nakopleno = fl_t729; /* пусть «накоплено» */
      fl_value fl_t733 = fl_nothing();
      FL_TRY(fl_variant_new(ctx, "В кавычках", NULL, NULL, 0, &fl_t733, error));
      return kompilyator_flang_s_metkoy(ctx, sostoyanie, fl_t733, zakryvayuschaya, nakopleno, nomer, mesto, result, error);
    }
  }
}

