      FL_TRY(kompilyator_flang_shagnut(ctx, r, &fl_t1544, error));
      r = fl_t1544;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Пропустить переводы", error));
