      fl_value fl_t9954 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t9952, gotovye, &fl_t9954, error));
      arnosti = hvost;
      zanyatye = fl_t9951;
      gotovye = fl_t9954;
