/* Тело «Аргумент по номеру»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_argument_po_nomeru_body(fl_ctx *ctx, fl_value argumenty, fl_value nomer, fl_value *result, fl_error *error) {
  for (;;) {
    fl_value fl_t16110 = fl_nothing();
    FL_TRY(fl_mod(ctx, nomer, fl_number(1.0), &fl_t16110, error));
    bool fl_t16111 = false;
    FL_TRY(fl_cond(ctx, fl_flag(fl_equal(fl_t16110, fl_number(0.0))), &fl_t16111, error));
    fl_value fl_t16112 = fl_nothing();
    if (fl_t16111) {
      fl_value fl_t16113 = fl_nothing();
      FL_TRY(fl_gte(ctx, nomer, fl_number(0.0), &fl_t16113, error));
      fl_t16112 = fl_t16113;
    } else {
      fl_t16112 = fl_flag(false);
    }
    bool fl_t16114 = false;
    FL_TRY(fl_cond(ctx, fl_t16112, &fl_t16114, error));
    fl_value fl_t16115 = fl_nothing();
    if (fl_t16114) {
      fl_value fl_t16116 = fl_nothing(); /* «длина» */
      FL_TRY(fl_b_dlina(ctx, argumenty, &fl_t16116, error));
      fl_value fl_t16117 = fl_nothing();
      FL_TRY(fl_lt(ctx, nomer, fl_t16116, &fl_t16117, error));
      fl_t16115 = fl_t16117;
    } else {
      fl_t16115 = fl_flag(false);
    }
    bool fl_t16118 = false;
    FL_TRY(fl_cond(ctx, fl_t16115, &fl_t16118, error));
    if (fl_t16118) {
      fl_value fl_t16119 = fl_nothing();
      FL_TRY(fl_add(ctx, nomer, fl_number(1.0), &fl_t16119, error));
      fl_value fl_t16120 = fl_nothing(); /* «элемент» */
      FL_TRY(fl_b_element(ctx, fl_t16119, argumenty, &fl_t16120, error));
      *result = fl_t16120;
      return FL_OK;
    } else {
      if (fl_chain_empty(argumenty)) {
        return kompilyator_flang_uzel_nichto(ctx, result, error);
      } else if (fl_chain_cons(argumenty)) {
        const fl_value golova = fl_chain_head(argumenty); /* голова «голова» */
        const fl_value hvost = fl_chain_tail(argumenty); /* хвост «хвост» */
        fl_value fl_t16121 = fl_nothing();
        FL_TRY(fl_lte(ctx, nomer, fl_number(0.0), &fl_t16121, error));
        bool fl_t16122 = false;
        FL_TRY(fl_cond(ctx, fl_t16121, &fl_t16122, error));
        if (fl_t16122) {
          *result = golova;
          return FL_OK;
        } else {
          fl_value fl_t16123 = fl_nothing();
          FL_TRY(fl_sub(ctx, nomer, fl_number(1.0), &fl_t16123, error));
          argumenty = hvost;
          nomer = fl_t16123;
          /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
          FL_TRY(fl_tick(ctx, "Аргумент по номеру", error));
          continue;
        }
      } else {
        return fl_match_fail(ctx, argumenty, error);
      }
    }
  }
}

